__hydrateVak("vmbo","ec",{"A":{"sv":[{"v":"Wat betekent koopkracht?","o":["Wat je kunt kopen","Wat je totaal spaart","Wat je totaal leent","Wat je aan belasting betaalt"],"c":0,"d":1,"u":"Wat je met je inkomen kunt kopen.","uo":["Klopt: wat je met je inkomen kunt kopen.","Sparen is iets anders.","Lenen is iets anders.","Belasting is iets anders."],"uh":"Wat je kunt kopen: Wat je met je inkomen kunt kopen."},{"v":"Wat gebeurt er bij inflatie?","o":["De prijzen dalen","De prijzen stijgen","De lonen dalen mee","Het geld verdwijnt"],"c":1,"d":2,"u":"Bij inflatie stijgen de prijzen.","uo":["Dat is deflatie.","Klopt: bij inflatie stijgen de prijzen.","Lonen dalen niet automatisch.","Geld verdwijnt niet."],"uh":"De prijzen stijgen: Bij inflatie stijgen de prijzen."},{"v":"Wat is een indexcijfer?","o":["Een soort belasting","Een spaarrekening","Een getal dat een verandering toont","Een muntsoort"],"c":2,"d":1,"u":"Een verandering ten opzichte van een basisjaar (100).","uo":["Geen belasting.","Geen spaarrekening.","Klopt: een verandering ten opzichte van een basisjaar (100).","Geen muntsoort."],"uh":"Een getal dat een verandering toont: Een verandering ten opzichte van een basisjaar (100)."},{"v":"Waarvoor betaal je premie?","o":["Voor een lening","Voor belasting","Voor sparen","Voor een verzekering"],"c":3,"d":1,"u":"Premie betaal je voor een verzekering.","uo":["Een lening betaal je met rente terug.","Belasting is iets anders.","Sparen kost geen premie.","Klopt: premie betaal je voor een verzekering."],"uh":"Voor een verzekering: Premie betaal je voor een verzekering."},{"v":"Wat is je eigen risico bij een verzekering?","o":["Het deel dat je zelf betaalt","De premie per maand","De totale schade","Het spaargeld"],"c":0,"d":2,"u":"Het deel van de schade dat je zelf betaalt.","uo":["Klopt: het deel van de schade dat je zelf betaalt.","Dat is de premie.","De verzekeraar dekt de rest.","Sparen is iets anders."],"uh":"Het deel dat je zelf betaalt: Het deel van de schade dat je zelf betaalt."},{"v":"Je prijzen stijgen 5%, je loon 2%. Wat gebeurt met je koopkracht?","o":["Die stijgt","Die daalt","Die blijft gelijk","Die verdwijnt"],"c":1,"d":3,"u":"Je koopkracht daalt.","uo":["Nee, de prijzen stijgen harder.","Klopt: je koopkracht daalt.","Nee, er is een verschil.","Koopkracht verdwijnt niet."],"uh":"Die daalt: Je koopkracht daalt."},{"v":"Wat is het verschil tussen sparen en uitgeven?","o":["Sparen kost meer","Beide zijn hetzelfde","Sparen bewaar je, uitgeven besteed je","Uitgeven is verboden"],"c":2,"d":2,"u":"Sparen bewaar je, uitgeven besteed je.","uo":["Sparen kost niets extra.","Ze zijn niet hetzelfde.","Klopt: sparen bewaar je, uitgeven besteed je.","Uitgeven mag gewoon."],"uh":"Sparen bewaar je, uitgeven besteed je."},{"v":"Wat is een budget?","o":["Een soort belasting","Een verzekering","Een lening","Een overzicht van inkomsten en uitgaven"],"c":3,"d":1,"u":"Een overzicht van inkomsten en uitgaven.","uo":["Geen belasting.","Geen verzekering.","Geen lening.","Klopt: een overzicht van inkomsten en uitgaven."],"uh":"Een overzicht van inkomsten en uitgaven."},{"v":"Wat is reëel inkomen?","o":["Inkomen na inflatie","Inkomen in euro's","Je spaargeld","Je uitgaven"],"c":0,"d":2,"u":"Inkomen gecorrigeerd voor inflatie.","uo":["Klopt: inkomen gecorrigeerd voor inflatie.","Dat is nominaal inkomen.","Sparen is iets anders.","Uitgaven zijn iets anders."],"uh":"Inkomen na inflatie: Inkomen gecorrigeerd voor inflatie."},{"v":"Wat betekent deflatie?","o":["Prijzen stijgen","Prijzen dalen","Lonen stijgen","Belasting stijgt"],"c":1,"d":1,"u":"Bij deflatie dalen de prijzen.","uo":["Dat is inflatie.","Klopt: bij deflatie dalen de prijzen.","Lonen zijn iets anders.","Belasting is iets anders."],"uh":"Prijzen dalen: Bij deflatie dalen de prijzen."},{"v":"Waarom sluit je een verzekering af?","o":["Om te sparen","Om te lenen","Om je te beschermen tegen grote kosten","Om belasting te betalen"],"c":2,"d":2,"u":"Bescherming tegen grote onverwachte kosten.","uo":["Sparen is iets anders.","Lenen is iets anders.","Klopt: bescherming tegen grote onverwachte kosten.","Belasting is iets anders."],"uh":"Om je te beschermen tegen grote kosten: Bescherming tegen grote onverwachte kosten."},{"v":"Wat is nominaal inkomen?","o":["Inkomen na inflatie","Je koopkracht","Je spaargeld","Inkomen in euro's"],"c":3,"d":2,"u":"Inkomen in euro's, zonder correctie.","uo":["Dat is reëel inkomen.","Koopkracht is iets anders.","Sparen is iets anders.","Klopt: inkomen in euro's, zonder correctie."],"uh":"Inkomen in euro's, zonder correctie."},{"v":"Wat is budgetteren?","o":["Je uitgaven plannen","Meer geld lenen","Alles snel uitgeven","Belasting ontwijken"],"c":0,"d":1,"u":"Je uitgaven plannen binnen je inkomen.","uo":["Klopt: je uitgaven plannen binnen je inkomen.","Lenen is iets anders.","Dat is het tegenovergestelde.","Dat mag niet."],"uh":"Je uitgaven plannen binnen je inkomen."},{"v":"Wat is nodig voor meer koopkracht?","o":["Prijzen die veel harder stijgen dan lonen","Loon dat harder stijgt dan de prijzen","Meer lenen bij de bank","Hogere belasting betalen"],"c":1,"d":3,"u":"Je loon stijgt harder dan de prijzen.","uo":["Dan daalt je koopkracht juist.","Klopt: je loon stijgt harder dan de prijzen.","Lenen helpt niet blijvend.","Hogere belasting helpt niet."],"uh":"Loon dat harder stijgt dan de prijzen: Je loon stijgt harder dan de prijzen."}],"begrippen":[{"t":"Koopkracht","d":"hoeveel je met je inkomen kunt kopen"},{"t":"Inkomen","d":"het geld dat je ontvangt, bijvoorbeeld loon"},{"t":"Uitgaven","d":"het geld dat je besteedt"},{"t":"Sparen","d":"geld dat je niet uitgeeft maar bewaart"},{"t":"Budget","d":"een overzicht van verwachte inkomsten en uitgaven"},{"t":"Budgetteren","d":"je uitgaven plannen binnen je inkomen"},{"t":"Inflatie","d":"een algemene stijging van de prijzen"},{"t":"Deflatie","d":"een algemene daling van de prijzen"},{"t":"Indexcijfer","d":"een getal dat een verandering ten opzichte van een basisjaar weergeeft"},{"t":"Reëel inkomen","d":"je inkomen gecorrigeerd voor inflatie"},{"t":"Nominaal inkomen","d":"je inkomen in euro's zonder correctie voor inflatie"},{"t":"Verzekering","d":"een afspraak waarbij je premie betaalt tegen financiële risico's"},{"t":"Premie","d":"het bedrag dat je periodiek voor een verzekering betaalt"},{"t":"Eigen risico","d":"het deel van de schade dat je zelf betaalt"}],"sam":"<div class=\"sam-intro\"><strong>Koopkracht</strong> is hoeveel je met je inkomen kunt kopen. Door <strong>inflatie</strong> daalt je koopkracht als je loon niet meestijgt. Met een <strong>indexcijfer</strong> reken je veranderingen uit, en met een <strong>verzekering</strong> bescherm je je tegen financiële risico's.</div><div class=\"sam-head\">1. Inkomen, uitgaven en koopkracht</div><p>Je <strong>inkomen</strong> is het geld dat je ontvangt, je <strong>uitgaven</strong> is het geld dat je besteedt. Wat je niet uitgeeft, kun je <strong>sparen</strong>. Met een <strong>budget</strong> (een overzicht van inkomsten en uitgaven) hou je overzicht; <strong>budgetteren</strong> is je uitgaven vooraf plannen.</p><p>Je <strong>koopkracht</strong> zegt hoeveel je met dat inkomen daadwerkelijk kunt kopen.</p><div class=\"sam-head\">2. Inflatie en je koopkracht</div><p><strong>Inflatie</strong> is een algemene stijging van de prijzen, <strong>deflatie</strong> een daling. Een <strong>indexcijfer</strong> laat een verandering zien ten opzichte van een basisjaar (dat op 100 staat).</p><p>Je <strong>nominaal inkomen</strong> is je inkomen in euro's; je <strong>reëel inkomen</strong> is dat inkomen gecorrigeerd voor inflatie. Stijgen de prijzen harder dan je loon, dan daalt je koopkracht.</p><div class=\"sam-worked\"><div class=\"sam-worked-h\">✍️ Voorbeeldopgave</div><div class=\"sam-worked-q\">De prijzen stijgen met 4% (indexcijfer 104). Je loon stijgt met 2%. Wat gebeurt er met je koopkracht?</div><ol class=\"sam-worked-steps\"><li>Vergelijk de stijging van de prijzen met die van je loon.</li><li>De prijzen stijgen harder (4%) dan je loon (2%).</li></ol><div class=\"sam-worked-ans\">✅ Je koopkracht daalt: je kunt minder kopen dan eerst.</div></div><div class=\"sam-head\">3. Je beschermen met een verzekering</div><p>Een <strong>verzekering</strong> beschermt je tegen grote, onverwachte kosten. Je betaalt daarvoor periodiek een <strong>premie</strong>. Bij schade betaal je vaak eerst zelf een deel, het <strong>eigen risico</strong>; de rest vergoedt de verzekeraar.</p><div class=\"sam-head\">Begrippen op een rij</div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Koopkracht</div><div class=\"sam-definitie-body\">hoeveel je met je inkomen kunt kopen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Inkomen</div><div class=\"sam-definitie-body\">het geld dat je ontvangt, bijvoorbeeld loon.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Uitgaven</div><div class=\"sam-definitie-body\">het geld dat je besteedt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Sparen</div><div class=\"sam-definitie-body\">geld dat je niet uitgeeft maar bewaart.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Budget</div><div class=\"sam-definitie-body\">een overzicht van verwachte inkomsten en uitgaven.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Budgetteren</div><div class=\"sam-definitie-body\">je uitgaven plannen binnen je inkomen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Inflatie</div><div class=\"sam-definitie-body\">een algemene stijging van de prijzen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Deflatie</div><div class=\"sam-definitie-body\">een algemene daling van de prijzen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Indexcijfer</div><div class=\"sam-definitie-body\">een getal dat een verandering ten opzichte van een basisjaar weergeeft.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Reëel inkomen</div><div class=\"sam-definitie-body\">je inkomen gecorrigeerd voor inflatie.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Nominaal inkomen</div><div class=\"sam-definitie-body\">je inkomen in euro's zonder correctie voor inflatie.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Verzekering</div><div class=\"sam-definitie-body\">een afspraak waarbij je premie betaalt tegen financiële risico's.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Premie</div><div class=\"sam-definitie-body\">het bedrag dat je periodiek voor een verzekering betaalt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Eigen risico</div><div class=\"sam-definitie-body\">het deel van de schade dat je zelf betaalt.</div></div><div class=\"sam-onthoud\"><b>Let op de verschillen.</b> <b>«Koopkracht»</b> is wat je inkomen kan kopen, terwijl <b>«Reëel inkomen»</b> inkomen na inflatie is. <b>«Inkomen»</b> is geld dat je ontvangt, terwijl <b>«Uitgaven»</b> geld dat je besteedt is. <b>«Sparen»</b> is geld bewaren, terwijl <b>«Uitgaven»</b> geld dat je besteedt is. <b>«Budget»</b> is overzicht inkomsten en uitgaven, terwijl <b>«Budgetteren»</b> uitgaven plannen is.</div>"},"B":{"sv":[{"v":"Wat geeft garantie je recht op?","o":["Herstel of vervanging bij een gebrek","Een lager bedrag","Gratis producten","Meer bedenktijd"],"c":0,"d":2,"u":"Herstel of vervanging bij een gebrek.","uo":["Klopt: herstel of vervanging bij een gebrek.","Garantie gaat niet over korting.","Niet zomaar gratis.","Dat is iets anders."],"uh":"Herstel of vervanging bij een gebrek."},{"v":"Je koopt online een jas. Welk recht heb je?","o":["Geen enkel recht","Bedenktijd om te retourneren","Alleen garantie","Altijd gratis verzending"],"c":1,"d":2,"u":"Bij online kopen heb je bedenktijd.","uo":["Je hebt wel rechten.","Klopt: bij online kopen heb je bedenktijd.","Er is meer dan garantie.","Verzending is niet gegarandeerd gratis."],"uh":"Bedenktijd om te retourneren: Bij online kopen heb je bedenktijd."},{"v":"Wat doet de Consumentenbond?","o":["Geld uitlenen","Belasting innen","Producten testen en adviseren","Producten maken"],"c":2,"d":1,"u":"Test producten en geeft advies.","uo":["Dat doet een bank.","Dat doet de Belastingdienst.","Klopt: test producten en geeft advies.","Dat doet een fabriek."],"uh":"Producten testen en adviseren: Test producten en geeft advies."},{"v":"Wat laat een keurmerk zien?","o":["De prijs","De maker","De houdbaarheid","Dat het aan eisen voldoet"],"c":3,"d":2,"u":"Dat een product aan bepaalde eisen voldoet.","uo":["Niet de prijs.","Niet de maker.","Niet per se de houdbaarheid.","Klopt: dat een product aan bepaalde eisen voldoet."],"uh":"Dat het aan eisen voldoet: Dat een product aan bepaalde eisen voldoet."},{"v":"Wat is een koopovereenkomst?","o":["De afspraak tussen koper en verkoper","Een verzekering","Een lening","Een belasting"],"c":0,"d":1,"u":"De afspraak tussen koper en verkoper.","uo":["Klopt: de afspraak tussen koper en verkoper.","Geen verzekering.","Geen lening.","Geen belasting."],"uh":"De afspraak tussen koper en verkoper."},{"v":"Je product is na een week kapot. Wat doe je?","o":["Niets, pech gehad","Een klacht indienen","Er nog een kopen","Belasting betalen"],"c":1,"d":3,"u":"Een klacht indienen bij de verkoper.","uo":["Je hebt rechten.","Klopt: een klacht indienen bij de verkoper.","Dat helpt niet.","Niet relevant."],"uh":"Een klacht indienen bij de verkoper."},{"v":"Wat is bedenktijd?","o":["Tijd om te lenen","Tijd om te sparen","Tijd om een aankoop te annuleren","Tijd om belasting te betalen"],"c":2,"d":1,"u":"De periode om een aankoop te annuleren.","uo":["Lenen is iets anders.","Sparen is iets anders.","Klopt: de periode om een aankoop te annuleren.","Belasting is iets anders."],"uh":"Tijd om een aankoop te annuleren: De periode om een aankoop te annuleren."},{"v":"Wat zijn algemene voorwaarden?","o":["De prijs van een product","Een soort verzekering","Een keurmerk","De regels bij een koop"],"c":3,"d":2,"u":"De regels die bij een koopovereenkomst horen.","uo":["Niet de prijs.","Geen verzekering.","Geen keurmerk.","Klopt: de regels die bij een koopovereenkomst horen."],"uh":"De regels die bij een koopovereenkomst horen."},{"v":"Wat is een consument?","o":["Iemand die koopt en gebruikt","Een fabriek","Een verkoper","De overheid"],"c":0,"d":1,"u":"Iemand die producten koopt en gebruikt.","uo":["Klopt: iemand die producten koopt en gebruikt.","Een fabriek maakt producten.","Een verkoper verkoopt juist.","De overheid is iets anders."],"uh":"Iemand die producten koopt en gebruikt."},{"v":"Waarvoor kun je bij de Consumentenbond terecht?","o":["Voor een lening","Voor advies over producten","Voor belasting","Voor een baan"],"c":1,"d":2,"u":"Voor advies en tests over producten.","uo":["Dat doet een bank.","Klopt: voor advies en tests over producten.","Dat doet de Belastingdienst.","Dat is iets anders."],"uh":"Voor advies en tests over producten."},{"v":"Wat is een aankoop op afstand?","o":["Ruilen met een vriend","Kopen in de winkel","Kopen via internet of telefoon","Iets huren"],"c":2,"d":1,"u":"Kopen zonder in de winkel te zijn.","uo":["Ruilen is iets anders.","Dat is juist in de winkel.","Klopt: kopen zonder in de winkel te zijn.","Huren is iets anders."],"uh":"Kopen via internet of telefoon: Kopen zonder in de winkel te zijn."},{"v":"Waarom zijn consumentenrechten belangrijk?","o":["Ze verhogen de prijs","Ze innen belasting","Ze maken producten","Ze beschermen de koper"],"c":3,"d":3,"u":"Ze beschermen de koper.","uo":["Ze gaan niet over de prijs.","Niet over belasting.","Ze maken geen producten.","Klopt: ze beschermen de koper."],"uh":"Ze beschermen de koper."}],"begrippen":[{"t":"Consumentenrecht","d":"de rechten die een koper heeft"},{"t":"Garantie","d":"het recht op herstel of vervanging bij een gebrek"},{"t":"Retourrecht","d":"het recht om een aankoop terug te sturen"},{"t":"Bedenktijd","d":"de periode waarin je een aankoop mag annuleren"},{"t":"Consumentenorganisatie","d":"een organisatie die opkomt voor kopers"},{"t":"Consumentenbond","d":"een organisatie die producten test en consumenten adviseert"},{"t":"Klacht","d":"een melding dat een product of dienst niet voldoet"},{"t":"Keurmerk","d":"een teken dat een product aan bepaalde eisen voldoet"},{"t":"Algemene voorwaarden","d":"de regels die bij een koopovereenkomst horen"},{"t":"Koopovereenkomst","d":"de afspraak tussen een koper en een verkoper"},{"t":"Aankoop op afstand","d":"een aankoop via internet, telefoon of post"},{"t":"Consument","d":"iemand die producten of diensten koopt en gebruikt"}],"sam":"<div class=\"sam-intro\">Als koper heb je <strong>consumentenrechten</strong>, zoals <strong>garantie</strong> en bij online kopen een <strong>bedenktijd</strong>. Een <strong>consumentenorganisatie</strong> test producten en helpt bij een <strong>klacht</strong>.</div><div class=\"sam-head\">1. Je rechten als koper</div><p>Bij een aankoop sluit je een <strong>koopovereenkomst</strong>, waarbij <strong>algemene voorwaarden</strong> horen. <strong>Garantie</strong> geeft je recht op herstel of vervanging bij een gebrek. Koop je op afstand (online), dan heb je <strong>bedenktijd</strong> en een <strong>retourrecht</strong> om de aankoop terug te sturen.</p><div class=\"sam-head\">2. Hulp en keurmerken</div><p>Een <strong>consumentenorganisatie</strong> zoals de <strong>Consumentenbond</strong> test producten en geeft advies. Ben je ontevreden, dan dien je een <strong>klacht</strong> in bij de verkoper. Een <strong>keurmerk</strong> laat vooraf zien dat een product aan bepaalde eisen voldoet.</p><div class=\"sam-head\">Begrippen op een rij</div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Consumentenrecht</div><div class=\"sam-definitie-body\">de rechten die een koper heeft.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Garantie</div><div class=\"sam-definitie-body\">het recht op herstel of vervanging bij een gebrek.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Retourrecht</div><div class=\"sam-definitie-body\">het recht om een aankoop terug te sturen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Bedenktijd</div><div class=\"sam-definitie-body\">de periode waarin je een aankoop mag annuleren.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Consumentenorganisatie</div><div class=\"sam-definitie-body\">een organisatie die opkomt voor kopers.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Consumentenbond</div><div class=\"sam-definitie-body\">een organisatie die producten test en consumenten adviseert.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Klacht</div><div class=\"sam-definitie-body\">een melding dat een product of dienst niet voldoet.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Keurmerk</div><div class=\"sam-definitie-body\">een teken dat een product aan bepaalde eisen voldoet.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Algemene voorwaarden</div><div class=\"sam-definitie-body\">de regels die bij een koopovereenkomst horen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Koopovereenkomst</div><div class=\"sam-definitie-body\">de afspraak tussen een koper en een verkoper.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Aankoop op afstand</div><div class=\"sam-definitie-body\">een aankoop via internet, telefoon of post.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Consument</div><div class=\"sam-definitie-body\">iemand die producten of diensten koopt en gebruikt.</div></div><div class=\"sam-onthoud\"><b>Let op de verschillen.</b> <b>«Consumentenrecht»</b> is rechten van de koper, terwijl <b>«Garantie»</b> herstel bij een gebrek is. <b>«Garantie»</b> is herstel bij een gebrek, terwijl <b>«Retourrecht»</b> aankoop terugsturen is. <b>«Retourrecht»</b> is aankoop terugsturen, terwijl <b>«Bedenktijd»</b> periode om te annuleren is. <b>«Consumentenorganisatie»</b> is komt op voor kopers, terwijl <b>«Consumentenbond»</b> test en adviseert is.</div>"},"C":{"sv":[{"v":"Wat is je brutoloon?","o":["Je loon vóór aftrek","Je loon na aftrek","Je spaargeld","Je uitkering"],"c":0,"d":1,"u":"Je loon vóór aftrek van belasting en premies.","uo":["Klopt: je loon vóór aftrek van belasting en premies.","Dat is nettoloon.","Sparen is iets anders.","Een uitkering is iets anders."],"uh":"Je loon vóór aftrek van belasting en premies."},{"v":"Wat blijft over na aftrek van belasting en premies?","o":["Het brutoloon","Het nettoloon","De loonheffing","De cao"],"c":1,"d":2,"u":"Het nettoloon.","uo":["Dat is juist vóór aftrek.","Klopt: het nettoloon.","Dat wordt juist ingehouden.","Een cao is een afspraak."],"uh":"Het nettoloon."},{"v":"Wat is loonheffing?","o":["Je vakantiegeld","Je spaarrente","Belasting en premies op je loon","Je bonus"],"c":2,"d":1,"u":"Belasting en premies die worden ingehouden.","uo":["Vakantiegeld is iets anders.","Rente is iets anders.","Klopt: belasting en premies die worden ingehouden.","Een bonus is iets anders."],"uh":"Belasting en premies die worden ingehouden."},{"v":"Wat is arbeidsverdeling?","o":["Iedereen doet alles","Niemand werkt","Alleen de baas werkt","Werk in aparte taken opdelen"],"c":3,"d":3,"u":"Het werk in aparte taken opsplitsen.","uo":["Dat is juist het tegenovergestelde.","Onjuist, het juiste antwoord is «Werk in aparte taken opdelen».","Onjuist, het juiste antwoord is «Werk in aparte taken opdelen».","Klopt: het werk in aparte taken opsplitsen."],"uh":"Werk in aparte taken opdelen: Het werk in aparte taken opsplitsen."},{"v":"Wat gebeurt er door specialisatie?","o":["Werk gaat sneller en beter","Mensen worden luier","Er is minder werk","De lonen dalen mee"],"c":0,"d":2,"u":"Je op één taak richten laat het beter gaan.","uo":["Klopt: je op één taak richten laat het beter gaan.","Niet luier, het juiste antwoord is «Werk gaat sneller en beter».","Onjuist, het juiste antwoord is «Werk gaat sneller en beter».","Onjuist, het juiste antwoord is «Werk gaat sneller en beter»."],"uh":"Werk gaat sneller en beter: Je op één taak richten laat het beter gaan."},{"v":"Wat is arbeidsproductiviteit?","o":["Het aantal werknemers","De productie per werknemer","Het totale loon","Het aantal machines"],"c":1,"d":2,"u":"De productie per werknemer per tijd.","uo":["Niet het aantal mensen.","Klopt: de productie per werknemer per tijd.","Niet het loon.","Niet het aantal machines."],"uh":"De productie per werknemer per tijd."},{"v":"Wie neemt mensen in dienst?","o":["De vakbond","De werknemer","De werkgever","De klant"],"c":2,"d":1,"u":"De werkgever neemt mensen aan.","uo":["De vakbond komt op voor werknemers.","De werknemer werkt in dienst.","Klopt: de werkgever neemt mensen aan.","De klant koopt."],"uh":"De werkgever neemt mensen aan."},{"v":"Wat staat er in een cao?","o":["De prijs van producten","De belastingtarieven","De koers van de euro","Afspraken over arbeidsvoorwaarden"],"c":3,"d":2,"u":"Afspraken over het werk voor een bedrijfstak.","uo":["Niet over productprijzen.","Niet over belasting.","Niet over de euro.","Klopt: afspraken over het werk voor een bedrijfstak."],"uh":"Afspraken over het werk voor een bedrijfstak."},{"v":"Wat is het minimumloon?","o":["Het wettelijk laagste loon","Het hoogste loon","Het gemiddelde loon","Het loon van de baas"],"c":0,"d":1,"u":"Het wettelijk laagste toegestane loon.","uo":["Klopt: het wettelijk laagste toegestane loon.","Juist niet het hoogste.","Niet het gemiddelde.","Niet specifiek de baas."],"uh":"Het wettelijk laagste toegestane loon."},{"v":"Wat doet een vakbond?","o":["Producten verkopen","Opkomen voor werknemers","Belasting innen","Geld uitlenen"],"c":1,"d":2,"u":"De vakbond komt op voor werknemers.","uo":["Nee, dat doet een winkel.","Klopt: de vakbond komt op voor werknemers.","Dat doet de Belastingdienst.","Dat doet een bank."],"uh":"Opkomen voor werknemers: De vakbond komt op voor werknemers."},{"v":"Wat is een werknemer?","o":["Een klant","Iemand die personeel aanneemt","Iemand die in loondienst werkt","Een fabriek"],"c":2,"d":1,"u":"Iemand die in loondienst werkt.","uo":["Een klant koopt.","Dat is de werkgever.","Klopt: iemand die in loondienst werkt.","Een fabriek maakt producten."],"uh":"Iemand die in loondienst werkt."},{"v":"Wat is een productiefactor?","o":["Een soort belasting","Een verzekering","Een klant","Een middel om te produceren"],"c":3,"d":3,"u":"Een middel om mee te produceren, zoals arbeid.","uo":["Geen belasting.","Geen verzekering.","Geen klant, het juiste antwoord is «Een middel om te produceren».","Klopt: een middel om mee te produceren, zoals arbeid."],"uh":"Een middel om mee te produceren, zoals arbeid."}],"begrippen":[{"t":"Brutoloon","d":"je loon vóór aftrek van belasting en premies"},{"t":"Nettoloon","d":"je loon na aftrek van belasting en premies"},{"t":"Loonheffing","d":"de belasting en premies die van je loon worden ingehouden"},{"t":"Arbeidsverdeling","d":"het opsplitsen van werk in aparte taken"},{"t":"Specialisatie","d":"je toeleggen op één taak of vak"},{"t":"Arbeidsproductiviteit","d":"de productie per werknemer per tijd"},{"t":"Werknemer","d":"iemand die in loondienst werkt"},{"t":"Werkgever","d":"iemand of een bedrijf dat mensen in dienst neemt"},{"t":"Cao","d":"afspraken over arbeidsvoorwaarden voor een hele bedrijfstak"},{"t":"Minimumloon","d":"het wettelijk laagste loon dat betaald mag worden"},{"t":"Vakbond","d":"een organisatie die opkomt voor werknemers"},{"t":"Productiefactor","d":"een middel om mee te produceren, zoals arbeid of kapitaal"}],"sam":"<div class=\"sam-intro\">Van je <strong>brutoloon</strong> gaan belasting en premies af; wat overblijft is je <strong>nettoloon</strong>. Door <strong>arbeidsverdeling</strong> en <strong>specialisatie</strong> stijgt de <strong>arbeidsproductiviteit</strong>.</div><div class=\"sam-head\">1. Van brutoloon naar nettoloon</div><p>Je <strong>brutoloon</strong> is je loon vóór aftrek. Daar gaat de <strong>loonheffing</strong> (belasting en premies) vanaf. Wat je op je rekening krijgt, is je <strong>nettoloon</strong>.</p><div class=\"sam-worked\"><div class=\"sam-worked-h\">✍️ Voorbeeldopgave</div><div class=\"sam-worked-q\">Je brutoloon is € 2.000 en de loonheffing is € 550. Hoeveel is je nettoloon?</div><ol class=\"sam-worked-steps\"><li>Nettoloon = brutoloon − loonheffing.</li><li>Nettoloon = 2.000 − 550.</li></ol><div class=\"sam-worked-ans\">✅ Je nettoloon is € 1.450.</div></div><div class=\"sam-head\">2. Productiever werken</div><p>Door <strong>arbeidsverdeling</strong> splits je het werk in aparte taken, en door <strong>specialisatie</strong> legt iemand zich toe op één taak. Daardoor stijgt de <strong>arbeidsproductiviteit</strong>: de productie per werknemer.</p><div class=\"sam-head\">3. Werkgevers, werknemers en afspraken</div><p>Een <strong>werkgever</strong> neemt mensen in dienst, een <strong>werknemer</strong> werkt in loondienst. In een <strong>cao</strong> staan de arbeidsvoorwaarden voor een hele bedrijfstak, mede bepaald door <strong>vakbonden</strong>. Het <strong>minimumloon</strong> is het wettelijk laagste loon.</p><div class=\"sam-head\">Begrippen op een rij</div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Brutoloon</div><div class=\"sam-definitie-body\">je loon vóór aftrek van belasting en premies.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Nettoloon</div><div class=\"sam-definitie-body\">je loon na aftrek van belasting en premies.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Loonheffing</div><div class=\"sam-definitie-body\">de belasting en premies die van je loon worden ingehouden.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Arbeidsverdeling</div><div class=\"sam-definitie-body\">het opsplitsen van werk in aparte taken.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Specialisatie</div><div class=\"sam-definitie-body\">je toeleggen op één taak of vak.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Arbeidsproductiviteit</div><div class=\"sam-definitie-body\">de productie per werknemer per tijd.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Werknemer</div><div class=\"sam-definitie-body\">iemand die in loondienst werkt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Werkgever</div><div class=\"sam-definitie-body\">iemand of een bedrijf dat mensen in dienst neemt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Cao</div><div class=\"sam-definitie-body\">afspraken over arbeidsvoorwaarden voor een hele bedrijfstak.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Minimumloon</div><div class=\"sam-definitie-body\">het wettelijk laagste loon dat betaald mag worden.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Vakbond</div><div class=\"sam-definitie-body\">een organisatie die opkomt voor werknemers.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Productiefactor</div><div class=\"sam-definitie-body\">een middel om mee te produceren, zoals arbeid of kapitaal.</div></div><div class=\"sam-onthoud\"><b>Let op de verschillen.</b> <b>«Brutoloon»</b> is loon vóór aftrek, terwijl <b>«Nettoloon»</b> loon na aftrek is. <b>«Loonheffing»</b> is inhoudingen op je loon, terwijl <b>«Brutoloon»</b> loon vóór aftrek is. <b>«Arbeidsverdeling»</b> is werk in taken opdelen, terwijl <b>«Specialisatie»</b> je op één taak richten is. <b>«Arbeidsproductiviteit»</b> is productie per werknemer, terwijl <b>«Arbeidsverdeling»</b> werk in taken opdelen is.</div>"},"D":{"sv":[{"v":"Wat is de omzet?","o":["Prijs maal aantal verkocht","De winst","De kosten","De belasting"],"c":0,"d":1,"u":"De totale verkoopopbrengst, prijs maal aantal.","uo":["Klopt: de totale verkoopopbrengst, prijs maal aantal.","Winst is omzet min kosten.","Kosten zijn iets anders.","Belasting is iets anders."],"uh":"Prijs maal aantal verkocht: De totale verkoopopbrengst, prijs maal aantal."},{"v":"Een winkel heeft € 5.000 omzet en € 3.500 kosten. Hoeveel winst?","o":["€ 8.500","€ 1.500","€ 5.000","€ 3.500"],"c":1,"d":3,"u":"5.000 − 3.500 = € 1.500.","uo":["Je moet aftrekken, niet optellen.","Klopt: 5.000 − 3.500 = € 1.500.","Dat is de omzet.","Dat zijn de kosten."],"uh":"€ 1.500: 5.000 − 3.500 = € 1.500."},{"v":"Wat zijn constante kosten?","o":["De totale omzet","Kosten die meebewegen","Kosten die gelijk blijven","De winst"],"c":2,"d":1,"u":"Ze veranderen niet met de productie.","uo":["Omzet is iets anders.","Dat zijn variabele kosten.","Klopt: ze veranderen niet met de productie.","Winst is iets anders."],"uh":"Kosten die gelijk blijven: Ze veranderen niet met de productie."},{"v":"Wat zijn variabele kosten?","o":["Kosten die gelijk blijven","De vaste huur","De verzekering","Kosten die meebewegen met de productie"],"c":3,"d":3,"u":"Ze bewegen mee met de productie.","uo":["Dat zijn constante kosten.","Huur is meestal constant.","Verzekering is meestal constant.","Klopt: ze bewegen mee met de productie."],"uh":"Kosten die meebewegen met de productie: Ze bewegen mee met de productie."},{"v":"Waarover betaal je btw?","o":["Over de verkoopprijs","Over je spaargeld","Over je loon","Over een lening"],"c":0,"d":2,"u":"Btw zit op de verkoopprijs.","uo":["Klopt: btw zit op de verkoopprijs.","Niet over sparen.","Over loon betaal je loonbelasting.","Niet over een lening."],"uh":"Over de verkoopprijs: Btw zit op de verkoopprijs."},{"v":"Wat is winst?","o":["De totale omzet","Omzet min kosten","Alle kosten samen","De verkoopprijs"],"c":1,"d":1,"u":"Winst is omzet min kosten.","uo":["Dat is de omzet.","Klopt: winst is omzet min kosten.","Dat zijn de kosten.","De prijs van één product."],"uh":"Omzet min kosten: Winst is omzet min kosten."},{"v":"Wat is de winstmarge?","o":["De belasting","De totale omzet","Verkoopprijs min inkoopprijs","De vaste huur"],"c":2,"d":2,"u":"Het verschil tussen verkoop- en inkoopprijs.","uo":["Belasting is iets anders.","Omzet is iets anders.","Klopt: het verschil tussen verkoop- en inkoopprijs.","Huur is een kostenpost."],"uh":"Verkoopprijs min inkoopprijs: Het verschil tussen verkoop- en inkoopprijs."},{"v":"Wat betekent break-even?","o":["Veel winst maken","Verlies lijden","De hoogste omzet halen","Omzet gelijk aan de kosten"],"c":3,"d":3,"u":"De omzet is precies gelijk aan de kosten.","uo":["Nee, geen winst.","Nee, ook geen verlies.","Niet per se de hoogste.","Klopt: de omzet is precies gelijk aan de kosten."],"uh":"Omzet gelijk aan de kosten: De omzet is precies gelijk aan de kosten."},{"v":"Wat is het verschil tussen verkoop- en inkoopprijs?","o":["De winstmarge","De omzet","De btw","De vaste huur"],"c":0,"d":2,"u":"Dat verschil is de winstmarge.","uo":["Klopt: dat verschil is de winstmarge.","Omzet is prijs maal aantal.","Btw is een belasting.","Huur is een kostenpost."],"uh":"De winstmarge: Dat verschil is de winstmarge."},{"v":"Wat zijn kosten?","o":["De verkoopopbrengst","Wat je uitgeeft om te produceren","De gemaakte winst","Alleen de belasting"],"c":1,"d":2,"u":"Alles wat je uitgeeft om te produceren.","uo":["Dat is de omzet.","Klopt: alles wat je uitgeeft om te produceren.","Winst is iets anders.","Belasting is maar een deel."],"uh":"Wat je uitgeeft om te produceren: Alles wat je uitgeeft om te produceren."},{"v":"Wat is brutowinst?","o":["De premie","De totale kosten","Omzet min inkoopwaarde","Het nettoloon"],"c":2,"d":2,"u":"De omzet min de inkoopwaarde.","uo":["Premie hoort bij verzekeren.","Kosten zijn iets anders.","Klopt: de omzet min de inkoopwaarde.","Loon is iets anders."],"uh":"Omzet min inkoopwaarde: De omzet min de inkoopwaarde."},{"v":"Waarom betaalt een winkel btw af?","o":["Als extra spaargeld","Als winst voor de baas","Als loon voor personeel","Als belasting aan de overheid"],"c":3,"d":2,"u":"Btw draag je af aan de overheid.","uo":["Niet als spaargeld.","Btw is geen winst.","Btw is geen loon.","Klopt: btw draag je af aan de overheid."],"uh":"Als belasting aan de overheid: Btw draag je af aan de overheid."}],"begrippen":[{"t":"Omzet","d":"de totale verkoopopbrengst: prijs maal aantal"},{"t":"Verkoopprijs","d":"de prijs waarvoor je een product verkoopt"},{"t":"Inkoopprijs","d":"de prijs die je voor een product betaalt"},{"t":"Btw","d":"belasting die je over de verkoopprijs betaalt"},{"t":"Winst","d":"het bedrag dat overblijft na aftrek van de kosten"},{"t":"Kosten","d":"alles wat je uitgeeft om te produceren"},{"t":"Constante kosten","d":"kosten die niet veranderen met de productie"},{"t":"Variabele kosten","d":"kosten die meebewegen met de productie"},{"t":"Totale kosten","d":"de constante kosten plus de variabele kosten"},{"t":"Brutowinst","d":"de omzet min de inkoopwaarde van de verkochte producten"},{"t":"Winstmarge","d":"het verschil tussen verkoopprijs en inkoopprijs"},{"t":"Break-even","d":"het punt waarop de omzet precies gelijk is aan de kosten"}],"sam":"<div class=\"sam-intro\">De <strong>omzet</strong> is prijs maal aantal. Trek je de <strong>kosten</strong> ervan af, dan houd je <strong>winst</strong> over. Over de verkoopprijs betaal je <strong>btw</strong> aan de overheid.</div><div class=\"sam-head\">1. Omzet, kosten en winst</div><p>De <strong>omzet</strong> is de totale verkoopopbrengst: prijs maal aantal. De <strong>kosten</strong> is alles wat je uitgeeft om te produceren. De <strong>winst</strong> is wat overblijft als je de kosten van de omzet aftrekt.</p><div class=\"sam-worked\"><div class=\"sam-worked-h\">✍️ Voorbeeldopgave</div><div class=\"sam-worked-q\">Een bedrijf heeft een omzet van € 5.000 en kosten van € 3.500. Hoeveel winst maakt het?</div><ol class=\"sam-worked-steps\"><li>Winst = omzet − kosten.</li><li>Winst = 5.000 − 3.500.</li></ol><div class=\"sam-worked-ans\">✅ De winst is € 1.500.</div></div><div class=\"sam-head\">2. Constante en variabele kosten</div><p><strong>Constante kosten</strong> (zoals huur) veranderen niet met de productie; <strong>variabele kosten</strong> (zoals grondstoffen) bewegen wél mee. Samen vormen ze de <strong>totale kosten</strong>. Bij het <strong>break-even</strong>punt is de omzet precies gelijk aan de kosten: geen winst, geen verlies.</p><div class=\"sam-head\">3. Prijzen en btw</div><p>Het verschil tussen <strong>verkoopprijs</strong> en <strong>inkoopprijs</strong> is de <strong>winstmarge</strong>. Over de verkoopprijs reken je <strong>btw</strong>, die je afdraagt aan de overheid.</p><div class=\"sam-head\">Begrippen op een rij</div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Omzet</div><div class=\"sam-definitie-body\">de totale verkoopopbrengst: prijs maal aantal.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Verkoopprijs</div><div class=\"sam-definitie-body\">de prijs waarvoor je een product verkoopt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Inkoopprijs</div><div class=\"sam-definitie-body\">de prijs die je voor een product betaalt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Btw</div><div class=\"sam-definitie-body\">belasting die je over de verkoopprijs betaalt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Winst</div><div class=\"sam-definitie-body\">het bedrag dat overblijft na aftrek van de kosten.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Kosten</div><div class=\"sam-definitie-body\">alles wat je uitgeeft om te produceren.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Constante kosten</div><div class=\"sam-definitie-body\">kosten die niet veranderen met de productie.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Variabele kosten</div><div class=\"sam-definitie-body\">kosten die meebewegen met de productie.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Totale kosten</div><div class=\"sam-definitie-body\">de constante kosten plus de variabele kosten.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Brutowinst</div><div class=\"sam-definitie-body\">de omzet min de inkoopwaarde van de verkochte producten.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Winstmarge</div><div class=\"sam-definitie-body\">het verschil tussen verkoopprijs en inkoopprijs.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Break-even</div><div class=\"sam-definitie-body\">het punt waarop de omzet precies gelijk is aan de kosten.</div></div><div class=\"sam-onthoud\"><b>Let op de verschillen.</b> <b>«Omzet»</b> is prijs maal aantal, terwijl <b>«Winst»</b> opbrengst min kosten is. <b>«Verkoopprijs»</b> is prijs bij verkoop, terwijl <b>«Inkoopprijs»</b> prijs bij inkoop is. <b>«Kosten»</b> is uitgaven om te produceren, terwijl <b>«Omzet»</b> prijs maal aantal is. <b>«Constante kosten»</b> is blijven gelijk, terwijl <b>«Variabele kosten»</b> bewegen mee is.</div>"},"E":{"sv":[{"v":"Waarom heft de overheid belasting?","o":["Om collectieve voorzieningen te betalen","Om winst te maken","Om te sparen","Om te lenen"],"c":0,"d":2,"u":"Om wegen, onderwijs en veiligheid te betalen.","uo":["Klopt: om wegen, onderwijs en veiligheid te betalen.","De overheid maakt geen winst.","Niet om te sparen.","Niet om te lenen."],"uh":"Om collectieve voorzieningen te betalen: Om wegen, onderwijs en veiligheid te betalen."},{"v":"Wat is een directe belasting?","o":["Btw op producten","Belasting op inkomen","Accijns op benzine","Een keurmerk"],"c":1,"d":2,"u":"Directe belasting gaat over inkomen of winst.","uo":["Btw is indirect.","Klopt: directe belasting gaat over inkomen of winst.","Accijns is indirect.","Een keurmerk is geen belasting."],"uh":"Belasting op inkomen: Directe belasting gaat over inkomen of winst."},{"v":"Wat is een indirecte belasting?","o":["Een subsidie","Belasting op je inkomen","Belasting in de prijs (btw)","Een uitkering"],"c":2,"d":2,"u":"Die zit in de prijs, zoals btw.","uo":["Een subsidie is geen belasting.","Dat is directe belasting.","Klopt: die zit in de prijs, zoals btw.","Een uitkering is geen belasting."],"uh":"Belasting in de prijs (btw): Die zit in de prijs, zoals btw."},{"v":"Wat is een collectieve voorziening?","o":["Iets voor jou alleen","Een verzekering","Een lening","Iets dat de overheid voor iedereen regelt"],"c":3,"d":2,"u":"Iets dat de overheid voor iedereen regelt, zoals wegen.","uo":["Nee, juist voor iedereen.","Geen verzekering.","Geen lening.","Klopt: iets dat de overheid voor iedereen regelt, zoals wegen."],"uh":"Iets dat de overheid voor iedereen regelt, zoals wegen."},{"v":"Wat is accijns?","o":["Extra belasting op bv. benzine","Belasting op inkomen","Een subsidie","Een uitkering"],"c":0,"d":2,"u":"Extra belasting op producten zoals alcohol en benzine.","uo":["Klopt: extra belasting op producten zoals alcohol en benzine.","Dat is inkomstenbelasting.","Geen subsidie.","Geen uitkering."],"uh":"Extra belasting op producten zoals alcohol en benzine."},{"v":"Wat is een subsidie?","o":["Een belasting","Geld om iets te stimuleren","Een boete","Een lening"],"c":1,"d":1,"u":"Geld van de overheid om iets te stimuleren.","uo":["Geen belasting.","Klopt: geld van de overheid om iets te stimuleren.","Geen boete, het juiste antwoord is «Geld om iets te stimuleren».","Geen lening."],"uh":"Geld om iets te stimuleren: Geld van de overheid om iets te stimuleren."},{"v":"Wat is een uitkering?","o":["Een keurmerk","Een belasting","Geld bij te weinig inkomen","Een verzekeringspremie"],"c":2,"d":1,"u":"Geld van de overheid voor wie te weinig inkomen heeft.","uo":["Geen keurmerk.","Geen belasting.","Klopt: geld van de overheid voor wie te weinig inkomen heeft.","Een premie is iets anders."],"uh":"Geld bij te weinig inkomen: Geld van de overheid voor wie te weinig inkomen heeft."},{"v":"Wat staat er in de begroting van de overheid?","o":["De koers van de euro","De prijzen in de winkel","De rente bij de bank","Verwachte inkomsten en uitgaven"],"c":3,"d":2,"u":"De verwachte inkomsten en uitgaven.","uo":["Niet de euro.","Niet winkelprijzen.","Niet de rente.","Klopt: de verwachte inkomsten en uitgaven."],"uh":"Verwachte inkomsten en uitgaven: De verwachte inkomsten en uitgaven."},{"v":"Wat is de staatsschuld?","o":["Wat de overheid heeft geleend","Het spaargeld van de overheid","De totale belasting","De begroting"],"c":0,"d":2,"u":"Het totale bedrag dat de overheid heeft geleend.","uo":["Klopt: het totale bedrag dat de overheid heeft geleend.","Nee, juist schuld.","Niet de belasting.","De begroting is een plan."],"uh":"Wat de overheid heeft geleend: Het totale bedrag dat de overheid heeft geleend."},{"v":"Wat hoort bij infrastructuur?","o":["Spaargeld","Wegen en bruggen","Belasting","Verzekeringen"],"c":1,"d":1,"u":"Voorzieningen zoals wegen, bruggen en spoor.","uo":["Nee, het juiste antwoord is «Wegen en bruggen».","Klopt: voorzieningen zoals wegen, bruggen en spoor.","Nee, het juiste antwoord is «Wegen en bruggen».","Nee, het juiste antwoord is «Wegen en bruggen»."],"uh":"Wegen en bruggen: Voorzieningen zoals wegen, bruggen en spoor."},{"v":"Wat is een overheidstaak?","o":["Sparen bij een bank","Een taak van een bedrijf","Een taak voor de samenleving","Iets kopen in de winkel"],"c":2,"d":1,"u":"Een taak die de overheid voor de samenleving doet.","uo":["Dat is iets anders.","Dat doet een bedrijf.","Klopt: een taak die de overheid voor de samenleving doet.","Dat is iets anders."],"uh":"Een taak voor de samenleving: Een taak die de overheid voor de samenleving doet."},{"v":"Wat is het verschil tussen subsidie en uitkering?","o":["Beide zijn een belasting","Beide zijn een lening","Er is geen verschil","Subsidie stimuleert, uitkering helpt bij te weinig inkomen"],"c":3,"d":3,"u":"Subsidie stimuleert iets, een uitkering helpt bij te weinig inkomen.","uo":["Het is geen belasting.","Het is geen lening.","Er is wel verschil.","Klopt: subsidie stimuleert iets, een uitkering helpt bij te weinig inkomen."],"uh":"Subsidie stimuleert iets, een uitkering helpt bij te weinig inkomen."}],"begrippen":[{"t":"Belasting","d":"een verplichte betaling aan de overheid"},{"t":"Directe belasting","d":"belasting op inkomen of winst"},{"t":"Indirecte belasting","d":"belasting die in de prijs van producten zit"},{"t":"Inkomstenbelasting","d":"belasting die je over je inkomen betaalt"},{"t":"Accijns","d":"extra belasting op producten zoals alcohol en benzine"},{"t":"Collectieve voorziening","d":"iets dat de overheid voor iedereen regelt, zoals wegen"},{"t":"Subsidie","d":"een bijdrage van de overheid om iets te stimuleren"},{"t":"Uitkering","d":"geld van de overheid voor wie niet genoeg inkomen heeft"},{"t":"Begroting","d":"het overzicht van verwachte inkomsten en uitgaven van de overheid"},{"t":"Staatsschuld","d":"het totale bedrag dat de overheid heeft geleend"},{"t":"Infrastructuur","d":"voorzieningen zoals wegen, bruggen en spoor"},{"t":"Overheidstaak","d":"een taak die de overheid voor de samenleving uitvoert"}],"sam":"<div class=\"sam-intro\">De <strong>overheid</strong> heft <strong>belasting</strong> om <strong>collectieve voorzieningen</strong> zoals wegen en onderwijs te betalen. <strong>Directe belasting</strong> gaat over inkomen, <strong>indirecte belasting</strong> zit in de prijs.</div><div class=\"sam-head\">1. Waarom belasting?</div><p>De overheid betaalt <strong>collectieve voorzieningen</strong> die er voor iedereen zijn, zoals <strong>infrastructuur</strong>, onderwijs en veiligheid. Dat geld komt binnen via <strong>belasting</strong>: een verplichte betaling aan de staat. Zulke taken heten <strong>overheidstaken</strong>.</p><div class=\"sam-head\">2. Directe en indirecte belasting</div><p>Een <strong>directe belasting</strong> gaat over je inkomen of winst, zoals de <strong>inkomstenbelasting</strong>. Een <strong>indirecte belasting</strong> zit verwerkt in de prijs van producten, zoals de <strong>btw</strong>. Op sommige producten zit extra belasting, de <strong>accijns</strong>.</p><div class=\"sam-head\">3. De begroting</div><p>In de <strong>begroting</strong> zet de overheid de verwachte inkomsten en uitgaven op een rij. Geeft de overheid meer uit dan er binnenkomt, dan groeit de <strong>staatsschuld</strong>. Met een <strong>subsidie</strong> stimuleert de overheid iets; met een <strong>uitkering</strong> helpt ze wie te weinig inkomen heeft.</p><div class=\"sam-head\">Begrippen op een rij</div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Belasting</div><div class=\"sam-definitie-body\">een verplichte betaling aan de overheid.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Directe belasting</div><div class=\"sam-definitie-body\">belasting op inkomen of winst.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Indirecte belasting</div><div class=\"sam-definitie-body\">belasting die in de prijs van producten zit.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Inkomstenbelasting</div><div class=\"sam-definitie-body\">belasting die je over je inkomen betaalt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Accijns</div><div class=\"sam-definitie-body\">extra belasting op producten zoals alcohol en benzine.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Collectieve voorziening</div><div class=\"sam-definitie-body\">iets dat de overheid voor iedereen regelt, zoals wegen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Subsidie</div><div class=\"sam-definitie-body\">een bijdrage van de overheid om iets te stimuleren.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Uitkering</div><div class=\"sam-definitie-body\">geld van de overheid voor wie niet genoeg inkomen heeft.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Begroting</div><div class=\"sam-definitie-body\">het overzicht van verwachte inkomsten en uitgaven van de overheid.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Staatsschuld</div><div class=\"sam-definitie-body\">het totale bedrag dat de overheid heeft geleend.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Infrastructuur</div><div class=\"sam-definitie-body\">voorzieningen zoals wegen, bruggen en spoor.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Overheidstaak</div><div class=\"sam-definitie-body\">een taak die de overheid voor de samenleving uitvoert.</div></div><div class=\"sam-onthoud\"><b>Let op de verschillen.</b> <b>«Belasting»</b> is verplichte betaling aan de staat, terwijl <b>«Accijns»</b> extra belasting op producten is. <b>«Directe belasting»</b> is belasting op inkomen, terwijl <b>«Indirecte belasting»</b> belasting in de prijs is. <b>«Inkomstenbelasting»</b> is belasting over inkomen, terwijl <b>«Directe belasting»</b> belasting op inkomen is. <b>«Collectieve voorziening»</b> is voor iedereen geregeld, terwijl <b>«Subsidie»</b> geld om te stimuleren is.</div>"},"F":{"sv":[{"v":"Wat is import?","o":["Invoer uit het buitenland","Uitvoer naar buitenland","Belasting op producten","Sparen in het buitenland"],"c":0,"d":1,"u":"Invoer van goederen uit het buitenland.","uo":["Klopt: invoer van goederen uit het buitenland.","Dat is export.","Dat is iets anders.","Dat is iets anders."],"uh":"Invoer uit het buitenland: Invoer van goederen uit het buitenland."},{"v":"Wat is export?","o":["Invoer uit het buitenland","Uitvoer naar het buitenland","Een belasting","Een lening"],"c":1,"d":1,"u":"Uitvoer van goederen naar het buitenland.","uo":["Dat is import.","Klopt: uitvoer van goederen naar het buitenland.","Geen belasting.","Geen lening."],"uh":"Uitvoer naar het buitenland: Uitvoer van goederen naar het buitenland."},{"v":"Wat is een wisselkoers?","o":["Een belasting","De rente op sparen","De prijs van een munt in een andere","Een keurmerk"],"c":2,"d":2,"u":"De prijs van de ene munt in de andere.","uo":["Geen belasting.","Rente is iets anders.","Klopt: de prijs van de ene munt in de andere.","Geen keurmerk."],"uh":"De prijs van de ene munt in de andere."},{"v":"Wat is de euro?","o":["Een belasting","Een bank","Een wisselkoers","De munt van veel EU-landen"],"c":3,"d":1,"u":"De gezamenlijke munt van veel EU-landen.","uo":["Geen belasting.","Geen bank, het juiste antwoord is «De munt van veel EU-landen».","Een koers is iets anders.","Klopt: de gezamenlijke munt van veel EU-landen."],"uh":"De munt van veel EU-landen: De gezamenlijke munt van veel EU-landen."},{"v":"Wat is de Europese Unie?","o":["Een samenwerking van Europese landen","Een bedrijf","Een munt","Een belasting"],"c":0,"d":1,"u":"Een samenwerkingsverband van Europese landen.","uo":["Klopt: een samenwerkingsverband van Europese landen.","Geen bedrijf.","De munt is de euro.","Geen belasting."],"uh":"Een samenwerkingsverband van Europese landen."},{"v":"Wat is vrijhandel?","o":["Handel met veel drempels","Handel zonder belemmeringen","Handel verbieden","Alleen binnenlandse handel"],"c":1,"d":2,"u":"Handel zonder belemmeringen tussen landen.","uo":["Nee, juist zonder drempels.","Klopt: handel zonder belemmeringen tussen landen.","Nee, het juiste antwoord is «Handel zonder belemmeringen».","Nee, ook met het buitenland."],"uh":"Handel zonder belemmeringen tussen landen."},{"v":"Wat is protectionisme?","o":["Meer importeren","Vrij handelen","De eigen markt beschermen","Grenzen openstellen"],"c":2,"d":2,"u":"Eigen bedrijven beschermen tegen buitenlandse concurrentie.","uo":["Onjuist, het juiste antwoord is «De eigen markt beschermen».","Dat is vrijhandel.","Klopt: eigen bedrijven beschermen tegen buitenlandse concurrentie.","Onjuist, het juiste antwoord is «De eigen markt beschermen»."],"uh":"De eigen markt beschermen: Eigen bedrijven beschermen tegen buitenlandse concurrentie."},{"v":"Wat is de handelsbalans?","o":["Het spaargeld","De begroting","De wisselkoers","Het verschil tussen export en import"],"c":3,"d":3,"u":"Het verschil tussen export en import.","uo":["Nee, het juiste antwoord is «Het verschil tussen export en import».","De begroting is iets anders.","Een koers is iets anders.","Klopt: het verschil tussen export en import."],"uh":"Het verschil tussen export en import."},{"v":"Wat is globalisering?","o":["Landen raken wereldwijd verweven","Landen sluiten zich af","Alleen binnenlandse handel","Minder handel"],"c":0,"d":2,"u":"Landen raken wereldwijd steeds meer verweven.","uo":["Klopt: landen raken wereldwijd steeds meer verweven.","Juist het tegenovergestelde.","Nee, het juiste antwoord is «Landen raken wereldwijd verweven».","Nee, het juiste antwoord is «Landen raken wereldwijd verweven»."],"uh":"Landen raken wereldwijd steeds meer verweven."},{"v":"Wat is ontwikkelingssamenwerking?","o":["Handel met winst","Hulp aan armere landen","Belasting innen","Een lening bij de bank"],"c":1,"d":2,"u":"Hulp aan armere landen om zich te ontwikkelen.","uo":["Niet gericht op winst.","Klopt: hulp aan armere landen om zich te ontwikkelen.","Geen belasting.","Geen lening."],"uh":"Hulp aan armere landen om zich te ontwikkelen."},{"v":"Wat zijn invoerrechten?","o":["Een subsidie","Belasting op je loon","Belasting op ingevoerde goederen","Een keurmerk"],"c":2,"d":2,"u":"Belasting op goederen die je invoert.","uo":["Geen subsidie.","Dat is loonbelasting.","Klopt: belasting op goederen die je invoert.","Geen keurmerk."],"uh":"Belasting op goederen die je invoert."},{"v":"Wat is een voordeel van de interne markt van de EU?","o":["Meer grenzen","Meer invoerrechten","Hogere belasting","Vrije handel zonder grenzen"],"c":3,"d":3,"u":"Vrije handel binnen de EU zonder grenzen.","uo":["Juist minder grenzen.","Juist minder rechten.","Niet per se.","Klopt: vrije handel binnen de EU zonder grenzen."],"uh":"Vrije handel binnen de EU zonder grenzen."}],"begrippen":[{"t":"Import","d":"het invoeren van goederen uit het buitenland"},{"t":"Export","d":"het uitvoeren van goederen naar het buitenland"},{"t":"Handelsbalans","d":"het verschil tussen de export en de import"},{"t":"Wisselkoers","d":"de prijs van de ene munt uitgedrukt in de andere"},{"t":"Euro","d":"de gezamenlijke munt van veel EU-landen"},{"t":"Europese Unie","d":"een samenwerkingsverband van Europese landen"},{"t":"Interne markt","d":"de vrije handel binnen de EU zonder grenzen"},{"t":"Invoerrechten","d":"belasting op goederen die worden ingevoerd"},{"t":"Ontwikkelingssamenwerking","d":"hulp aan armere landen om zich te ontwikkelen"},{"t":"Vrijhandel","d":"handel zonder belemmeringen tussen landen"},{"t":"Protectionisme","d":"eigen bedrijven beschermen tegen buitenlandse concurrentie"},{"t":"Globalisering","d":"het steeds meer verweven raken van landen wereldwijd"}],"sam":"<div class=\"sam-intro\">Landen handelen met elkaar: <strong>import</strong> is invoer, <strong>export</strong> is uitvoer. Voor handel met andere munten geldt een <strong>wisselkoers</strong>. Binnen de <strong>Europese Unie</strong> is er vrije handel.</div><div class=\"sam-head\">1. Import en export</div><p><strong>Import</strong> is het invoeren van goederen uit het buitenland, <strong>export</strong> het uitvoeren ervan. Het verschil tussen export en import heet de <strong>handelsbalans</strong>.</p><div class=\"sam-head\">2. Geld over de grens</div><p>Handel je met een land met een andere munt, dan speelt de <strong>wisselkoers</strong>: de prijs van de ene munt in de andere. Veel EU-landen gebruiken dezelfde munt, de <strong>euro</strong>, zodat wisselen niet meer nodig is. Soms heft een land <strong>invoerrechten</strong> op buitenlandse goederen.</p><div class=\"sam-head\">3. Samenwerking en globalisering</div><p>De <strong>Europese Unie</strong> vormt één <strong>interne markt</strong> met vrije handel. Landen kiezen tussen <strong>vrijhandel</strong> (geen drempels) en <strong>protectionisme</strong> (eigen markt beschermen). Door <strong>globalisering</strong> raken landen wereldwijd verweven; met <strong>ontwikkelingssamenwerking</strong> worden armere landen geholpen.</p><div class=\"sam-head\">Begrippen op een rij</div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Import</div><div class=\"sam-definitie-body\">het invoeren van goederen uit het buitenland.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Export</div><div class=\"sam-definitie-body\">het uitvoeren van goederen naar het buitenland.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Handelsbalans</div><div class=\"sam-definitie-body\">het verschil tussen de export en de import.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Wisselkoers</div><div class=\"sam-definitie-body\">de prijs van de ene munt uitgedrukt in de andere.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Euro</div><div class=\"sam-definitie-body\">de gezamenlijke munt van veel EU-landen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Europese Unie</div><div class=\"sam-definitie-body\">een samenwerkingsverband van Europese landen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Interne markt</div><div class=\"sam-definitie-body\">de vrije handel binnen de EU zonder grenzen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Invoerrechten</div><div class=\"sam-definitie-body\">belasting op goederen die worden ingevoerd.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Ontwikkelingssamenwerking</div><div class=\"sam-definitie-body\">hulp aan armere landen om zich te ontwikkelen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Vrijhandel</div><div class=\"sam-definitie-body\">handel zonder belemmeringen tussen landen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Protectionisme</div><div class=\"sam-definitie-body\">eigen bedrijven beschermen tegen buitenlandse concurrentie.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Globalisering</div><div class=\"sam-definitie-body\">het steeds meer verweven raken van landen wereldwijd.</div></div><div class=\"sam-onthoud\"><b>Let op de verschillen.</b> <b>«Import»</b> is invoer uit buitenland, terwijl <b>«Export»</b> uitvoer naar buitenland is. <b>«Handelsbalans»</b> is export min import, terwijl <b>«Wisselkoers»</b> prijs van een munt is. <b>«Wisselkoers»</b> is prijs van een munt, terwijl <b>«Euro»</b> de munt van de eurozone is. <b>«Europese Unie»</b> is samenwerkende EU-landen, terwijl <b>«Interne markt»</b> vrije handel in de EU is.</div>"},"G":{"sv":[{"v":"Wat zijn milieukosten?","o":["De kosten van schade aan het milieu","De prijs van een product","De winst","De belasting"],"c":0,"d":2,"u":"De kosten van milieuschade.","uo":["Klopt: de kosten van milieuschade.","Niet de productprijs.","Winst is iets anders.","Belasting is iets anders."],"uh":"De kosten van milieuschade."},{"v":"Wat zijn externe kosten?","o":["Kosten die de maker betaalt","Kosten die de samenleving draagt","De gemaakte winst","De inkoopprijs"],"c":1,"d":2,"u":"Kosten die de samenleving draagt, niet de vervuiler.","uo":["Nee, juist niet de maker.","Klopt: kosten die de samenleving draagt, niet de vervuiler.","Winst is iets anders.","Iets anders."],"uh":"Kosten die de samenleving draagt, niet de vervuiler."},{"v":"Wat betekent het vervuiler-betaalt-principe?","o":["Niemand betaalt","De overheid betaalt alles","Wie vervuilt, betaalt","De klant betaalt nooit"],"c":2,"d":2,"u":"Wie vervuilt betaalt zelf de kosten.","uo":["Nee, het juiste antwoord is «Wie vervuilt, betaalt».","Nee, het juiste antwoord is «Wie vervuilt, betaalt».","Klopt: wie vervuilt betaalt zelf de kosten.","Nee, het juiste antwoord is «Wie vervuilt, betaalt»."],"uh":"Wie vervuilt betaalt zelf de kosten."},{"v":"Wat is een circulaire economie?","o":["Alles wordt weggegooid","Meer verbranden","Grondstoffen uitputten","Grondstoffen worden hergebruikt"],"c":3,"d":3,"u":"Een economie waarin grondstoffen worden hergebruikt.","uo":["Juist niet, het juiste antwoord is «Grondstoffen worden hergebruikt».","Nee, het juiste antwoord is «Grondstoffen worden hergebruikt».","Nee, het juiste antwoord is «Grondstoffen worden hergebruikt».","Klopt: een economie waarin grondstoffen worden hergebruikt."],"uh":"Grondstoffen worden hergebruikt: Een economie waarin grondstoffen worden hergebruikt."},{"v":"Wat gebeurt er bij recycling?","o":["Afval wordt nieuwe grondstof","Afval blijft liggen","Afval verdwijnt","Afval wordt duurder"],"c":0,"d":1,"u":"Afval wordt tot nieuwe grondstof verwerkt.","uo":["Klopt: afval wordt tot nieuwe grondstof verwerkt.","Nee, het juiste antwoord is «Afval wordt nieuwe grondstof».","Nee, het juiste antwoord is «Afval wordt nieuwe grondstof».","Niet per se."],"uh":"Afval wordt tot nieuwe grondstof verwerkt."},{"v":"Wat is uitputting van grondstoffen?","o":["Meer grondstoffen krijgen","Grondstoffen raken op","Grondstoffen hergebruiken","Grondstoffen sparen"],"c":1,"d":2,"u":"Grondstoffen raken op.","uo":["Nee, het juiste antwoord is «Grondstoffen raken op».","Klopt: grondstoffen raken op.","Dat is juist goed.","Nee, het juiste antwoord is «Grondstoffen raken op»."],"uh":"Grondstoffen raken op."},{"v":"Wat is duurzaam produceren?","o":["Alles wegwerpen","Zoveel mogelijk vervuilen","Produceren met zorg voor milieu","Grondstoffen uitputten"],"c":2,"d":1,"u":"Produceren met zorg voor mens en milieu.","uo":["Nee, het juiste antwoord is «Produceren met zorg voor milieu».","Nee, het juiste antwoord is «Produceren met zorg voor milieu».","Klopt: produceren met zorg voor mens en milieu.","Nee, het juiste antwoord is «Produceren met zorg voor milieu»."],"uh":"Produceren met zorg voor mens en milieu."},{"v":"Wat is een fossiele brandstof?","o":["Zonne-energie","Windenergie","Waterkracht","Aardolie"],"c":3,"d":1,"u":"Aardolie is fossiel en raakt op.","uo":["Duurzaam, het juiste antwoord is «Aardolie».","Duurzaam, het juiste antwoord is «Aardolie».","Duurzaam, het juiste antwoord is «Aardolie».","Klopt: aardolie is fossiel en raakt op."],"uh":"Aardolie is fossiel en raakt op."},{"v":"Waarom zijn externe kosten een probleem?","o":["De samenleving draait ervoor op","De maker betaalt te veel","Er is geen probleem","Producten worden gratis"],"c":0,"d":3,"u":"De samenleving betaalt de schade, niet de vervuiler.","uo":["Klopt: de samenleving betaalt de schade, niet de vervuiler.","Juist niet de maker.","Er is wel een probleem.","Nee, het juiste antwoord is «De samenleving draait ervoor op»."],"uh":"De samenleving betaalt de schade, niet de vervuiler."},{"v":"Wat is duurzame ontwikkeling?","o":["Snelle uitputting","Groei die de toekomst niet schaadt","Alleen nu belangrijk","Meer vervuiling"],"c":1,"d":2,"u":"Ontwikkeling die de toekomst niet schaadt.","uo":["Nee, het juiste antwoord is «Groei die de toekomst niet schaadt».","Klopt: ontwikkeling die de toekomst niet schaadt.","Nee, ook de toekomst telt.","Nee, het juiste antwoord is «Groei die de toekomst niet schaadt»."],"uh":"Groei die de toekomst niet schaadt: Ontwikkeling die de toekomst niet schaadt."},{"v":"Wat is groene energie?","o":["Steenkool","Aardgas","Energie die niet opraakt","Aardolie"],"c":2,"d":1,"u":"Uit bronnen die niet opraken, zoals zon en wind.","uo":["Fossiel, het juiste antwoord is «Energie die niet opraakt».","Fossiel, het juiste antwoord is «Energie die niet opraakt».","Klopt: uit bronnen die niet opraken, zoals zon en wind.","Fossiel, het juiste antwoord is «Energie die niet opraakt»."],"uh":"Energie die niet opraakt: Uit bronnen die niet opraken, zoals zon en wind."},{"v":"Wat is consuminderen?","o":["Meer kopen","Alles vervangen","Vaker weggooien","Bewust minder gebruiken"],"c":3,"d":2,"u":"Bewust minder kopen en gebruiken.","uo":["Juist niet, het juiste antwoord is «Bewust minder gebruiken».","Nee, het juiste antwoord is «Bewust minder gebruiken».","Nee, het juiste antwoord is «Bewust minder gebruiken».","Klopt: bewust minder kopen en gebruiken."],"uh":"Bewust minder kopen en gebruiken."}],"begrippen":[{"t":"Milieukosten","d":"de kosten van schade aan het milieu"},{"t":"Externe kosten","d":"kosten die niet de veroorzaker maar de samenleving draagt"},{"t":"Vervuiler-betaalt-principe","d":"wie vervuilt, betaalt zelf de kosten daarvan"},{"t":"Duurzaam produceren","d":"produceren met zorg voor mens en milieu"},{"t":"Circulaire economie","d":"een economie waarin grondstoffen worden hergebruikt"},{"t":"Recycling","d":"afval verwerken tot nieuwe grondstoffen"},{"t":"Grondstof","d":"een natuurlijke stof waarvan je iets maakt"},{"t":"Uitputting","d":"het opraken van grondstoffen"},{"t":"Duurzame ontwikkeling","d":"ontwikkeling die de toekomst niet schaadt"},{"t":"Fossiele brandstof","d":"brandstof uit resten van organismen, zoals olie en gas"},{"t":"Groene energie","d":"energie uit bronnen die niet opraken"},{"t":"Consuminderen","d":"bewust minder kopen en gebruiken"}],"sam":"<div class=\"sam-intro\">Produceren kost niet alleen geld maar ook <strong>milieukosten</strong>. Bij <strong>externe kosten</strong> draait de samenleving op voor de schade. <strong>Duurzaam produceren</strong> en een <strong>circulaire economie</strong> beperken de <strong>uitputting</strong> van grondstoffen.</div><div class=\"sam-head\">1. De kosten van vervuiling</div><p>Vervuiling brengt <strong>milieukosten</strong> met zich mee. Vaak zijn dat <strong>externe kosten</strong>: niet de vervuiler maar de samenleving betaalt. Met het <strong>vervuiler-betaalt-principe</strong> legt de overheid die kosten juist bij de veroorzaker.</p><div class=\"sam-head\">2. Duurzaam en circulair</div><p><strong>Duurzaam produceren</strong> houdt rekening met mens en milieu. In een <strong>circulaire economie</strong> worden grondstoffen steeds hergebruikt via <strong>recycling</strong>, zodat de <strong>uitputting</strong> van grondstoffen afneemt. Dat past bij <strong>duurzame ontwikkeling</strong>: groei die de toekomst niet schaadt.</p><div class=\"sam-head\">Begrippen op een rij</div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Milieukosten</div><div class=\"sam-definitie-body\">de kosten van schade aan het milieu.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Externe kosten</div><div class=\"sam-definitie-body\">kosten die niet de veroorzaker maar de samenleving draagt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Vervuiler-betaalt-principe</div><div class=\"sam-definitie-body\">wie vervuilt, betaalt zelf de kosten daarvan.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Duurzaam produceren</div><div class=\"sam-definitie-body\">produceren met zorg voor mens en milieu.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Circulaire economie</div><div class=\"sam-definitie-body\">een economie waarin grondstoffen worden hergebruikt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Recycling</div><div class=\"sam-definitie-body\">afval verwerken tot nieuwe grondstoffen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Grondstof</div><div class=\"sam-definitie-body\">een natuurlijke stof waarvan je iets maakt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Uitputting</div><div class=\"sam-definitie-body\">het opraken van grondstoffen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Duurzame ontwikkeling</div><div class=\"sam-definitie-body\">ontwikkeling die de toekomst niet schaadt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Fossiele brandstof</div><div class=\"sam-definitie-body\">brandstof uit resten van organismen, zoals olie en gas.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Groene energie</div><div class=\"sam-definitie-body\">energie uit bronnen die niet opraken.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Consuminderen</div><div class=\"sam-definitie-body\">bewust minder kopen en gebruiken.</div></div><div class=\"sam-onthoud\"><b>Let op de verschillen.</b> <b>«Milieukosten»</b> is kosten van milieuschade, terwijl <b>«Externe kosten»</b> samenleving betaalt de schade is. <b>«Vervuiler-betaalt-principe»</b> is vervuiler betaalt, terwijl <b>«Externe kosten»</b> samenleving betaalt de schade is. <b>«Duurzaam produceren»</b> is produceren met zorg, terwijl <b>«Circulaire economie»</b> grondstoffen hergebruiken is. <b>«Circulaire economie»</b> is grondstoffen hergebruiken, terwijl <b>«Recycling»</b> afval hergebruiken is.</div>"},"H":{"sv":[{"v":"Wat is rente?","o":["De vergoeding voor geld lenen of uitlenen","Een belasting","Je spaargeld","Een boete"],"c":0,"d":1,"u":"De vergoeding voor het gebruik van geld.","uo":["Klopt: de vergoeding voor het gebruik van geld.","Geen belasting.","Sparen is iets anders.","Geen boete, het juiste antwoord is «De vergoeding voor geld lenen of uitlenen»."],"uh":"De vergoeding voor het gebruik van geld."},{"v":"Wat is samengestelde interest?","o":["Rente over alleen het startbedrag","Rente ook over eerdere rente","Helemaal geen rente","Een belasting"],"c":1,"d":2,"u":"Je krijgt rente over de rente.","uo":["Dat is enkelvoudige interest.","Klopt: je krijgt rente over de rente.","Nee, het juiste antwoord is «Rente ook over eerdere rente».","Geen belasting."],"uh":"Rente ook over eerdere rente: Je krijgt rente over de rente."},{"v":"Wat is enkelvoudige interest?","o":["Helemaal geen rente","Rente over rente","Rente over alleen het startbedrag","Een lening"],"c":2,"d":2,"u":"Rente alleen over het oorspronkelijke bedrag.","uo":["Nee, het juiste antwoord is «Rente over alleen het startbedrag».","Dat is samengesteld.","Klopt: rente alleen over het oorspronkelijke bedrag.","Een lening is iets anders."],"uh":"Rente over alleen het startbedrag: Rente alleen over het oorspronkelijke bedrag."},{"v":"Je zet € 100 weg tegen 10% rente. Hoeveel rente in jaar 2 (samengesteld)?","o":["€ 10","€ 0","€ 100","€ 11"],"c":3,"d":3,"u":"10% over € 110 is € 11.","uo":["Dat is jaar 1.","Er is wel rente.","Veel te veel.","Klopt: 10% over € 110 is € 11."],"uh":"€ 11: 10% over € 110 is € 11."},{"v":"Wat is een hypotheek?","o":["Een lening voor een huis","Een spaarrekening","Een belasting","Een verzekering"],"c":0,"d":1,"u":"Een lening voor een huis, met het huis als onderpand.","uo":["Klopt: een lening voor een huis, met het huis als onderpand.","Nee, het juiste antwoord is «Een lening voor een huis».","Geen belasting.","Geen verzekering."],"uh":"Een lening voor een huis, met het huis als onderpand."},{"v":"Wat is onderpand?","o":["Je spaargeld","Bezit dat de bank mag verkopen bij niet-betalen","De rente","De premie"],"c":1,"d":2,"u":"Zekerheid voor de bank.","uo":["Nee, het juiste antwoord is «Bezit dat de bank mag verkopen bij niet-betalen».","Klopt: zekerheid voor de bank.","Rente is iets anders.","Premie hoort bij verzekeren."],"uh":"Bezit dat de bank mag verkopen bij niet-betalen: Zekerheid voor de bank."},{"v":"Wat is aflossing?","o":["Het sparen","De rente","Het terugbetalen van een lening","De premie"],"c":2,"d":1,"u":"Het terugbetalen van een lening.","uo":["Sparen is iets anders.","Rente is de vergoeding.","Klopt: het terugbetalen van een lening.","Premie is iets anders."],"uh":"Het terugbetalen van een lening."},{"v":"Wat doet de centrale bank?","o":["Producten verkopen","Belasting innen","Loon betalen","Het geld bewaken"],"c":3,"d":2,"u":"De centrale bank bewaakt de waarde van het geld.","uo":["Nee, het juiste antwoord is «Het geld bewaken».","Dat doet de Belastingdienst.","Nee, het juiste antwoord is «Het geld bewaken».","Klopt: de centrale bank bewaakt de waarde van het geld."],"uh":"Het geld bewaken: De centrale bank bewaakt de waarde van het geld."},{"v":"Wat is krediet?","o":["De mogelijkheid om te lenen","Een belasting","Je spaargeld","Een keurmerk"],"c":0,"d":2,"u":"De mogelijkheid om geld te lenen.","uo":["Klopt: de mogelijkheid om geld te lenen.","Geen belasting.","Sparen is iets anders.","Geen keurmerk."],"uh":"De mogelijkheid om geld te lenen."},{"v":"Wat gebeurt er bij inflatie met je geld?","o":["Het wordt meer waard","Het wordt minder waard","Het blijft gelijk","Het verdwijnt"],"c":1,"d":2,"u":"Door stijgende prijzen wordt geld minder waard.","uo":["Nee, minder.","Klopt: door stijgende prijzen wordt geld minder waard.","Nee, het juiste antwoord is «Het wordt minder waard».","Geld verdwijnt niet."],"uh":"Het wordt minder waard: Door stijgende prijzen wordt geld minder waard."},{"v":"Wat is sparen?","o":["Geld uitgeven","Geld lenen","Geld opzijzetten bij een bank","Belasting betalen"],"c":2,"d":1,"u":"Geld opzijzetten, vaak tegen rente.","uo":["Uitgeven is iets anders.","Dat is het tegenovergestelde.","Klopt: geld opzijzetten, vaak tegen rente.","Belasting is iets anders."],"uh":"Geld opzijzetten, vaak tegen rente."},{"v":"Waarom groeit spaargeld sneller met samengestelde interest?","o":["Omdat de bank meer geeft","Omdat je meer stort","Omdat de rente daalt","Omdat je rente over rente krijgt"],"c":3,"d":3,"u":"Je krijgt ook rente over de eerder ontvangen rente.","uo":["Niet zomaar.","Niet per se.","Nee, het juiste antwoord is «Omdat je rente over rente krijgt».","Klopt: je krijgt ook rente over de eerder ontvangen rente."],"uh":"Omdat je rente over rente krijgt: Je krijgt ook rente over de eerder ontvangen rente."}],"begrippen":[{"t":"Rente","d":"de vergoeding voor het lenen of uitlenen van geld"},{"t":"Samengestelde interest","d":"rente die je ook over eerder ontvangen rente krijgt"},{"t":"Enkelvoudige interest","d":"rente alleen over het oorspronkelijke bedrag"},{"t":"Sparen","d":"geld opzijzetten, vaak bij een bank tegen rente"},{"t":"Lenen","d":"geld tijdelijk van een ander gebruiken tegen rente"},{"t":"Hypotheek","d":"een lening voor een huis met het huis als onderpand"},{"t":"Centrale bank","d":"de bank die het geldbeleid van een land of de EU bepaalt"},{"t":"Rentestand","d":"de hoogte van de rente op een bepaald moment"},{"t":"Aflossing","d":"het terugbetalen van een lening"},{"t":"Onderpand","d":"bezit dat de bank mag verkopen als je niet terugbetaalt"},{"t":"Krediet","d":"de mogelijkheid om geld te lenen"},{"t":"Inflatie","d":"een algemene stijging van de prijzen"}],"sam":"<div class=\"sam-intro\">Wie geld leent of uitleent, betaalt of ontvangt <strong>rente</strong>. Bij <strong>samengestelde interest</strong> krijg je ook rente over eerder ontvangen rente. Een <strong>hypotheek</strong> is een lening voor een huis.</div><div class=\"sam-head\">1. Sparen, lenen en rente</div><p><strong>Rente</strong> is de vergoeding voor het gebruik van geld: je ontvangt rente over je <strong>sparen</strong> en betaalt rente als je gaat <strong>lenen</strong>. Een lening betaal je stapsgewijs terug via <strong>aflossing</strong>; de mogelijkheid om te lenen heet <strong>krediet</strong>.</p><div class=\"sam-head\">2. Rente over rente</div><p>Bij <strong>enkelvoudige interest</strong> krijg je elk jaar rente over alleen het startbedrag. Bij <strong>samengestelde interest</strong> krijg je rente over het bedrag inclusief de eerder bijgeschreven rente, waardoor je spaargeld sneller groeit.</p><div class=\"sam-worked\"><div class=\"sam-worked-h\">✍️ Voorbeeldopgave</div><div class=\"sam-worked-q\">Je zet € 100 weg tegen 10% rente per jaar. Hoeveel rente krijg je in het tweede jaar?</div><ol class=\"sam-worked-steps\"><li>Na jaar 1 heb je € 110 (€ 100 + € 10 rente).</li><li>In jaar 2 krijg je 10% over € 110, niet over € 100.</li></ol><div class=\"sam-worked-ans\">✅ € 11 rente: je krijgt rente over de rente (samengestelde interest).</div></div><div class=\"sam-head\">3. Lenen voor een huis</div><p>Een <strong>hypotheek</strong> is een lening voor een huis, met het huis als <strong>onderpand</strong>: betaal je niet terug, dan mag de bank het verkopen. De <strong>centrale bank</strong> bewaakt de waarde van het geld en beïnvloedt de rente.</p><div class=\"sam-head\">Begrippen op een rij</div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Rente</div><div class=\"sam-definitie-body\">de vergoeding voor het lenen of uitlenen van geld.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Samengestelde interest</div><div class=\"sam-definitie-body\">rente die je ook over eerder ontvangen rente krijgt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Enkelvoudige interest</div><div class=\"sam-definitie-body\">rente alleen over het oorspronkelijke bedrag.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Sparen</div><div class=\"sam-definitie-body\">geld opzijzetten, vaak bij een bank tegen rente.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Lenen</div><div class=\"sam-definitie-body\">geld tijdelijk van een ander gebruiken tegen rente.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Hypotheek</div><div class=\"sam-definitie-body\">een lening voor een huis met het huis als onderpand.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Centrale bank</div><div class=\"sam-definitie-body\">de bank die het geldbeleid van een land of de EU bepaalt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Rentestand</div><div class=\"sam-definitie-body\">de hoogte van de rente op een bepaald moment.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Aflossing</div><div class=\"sam-definitie-body\">het terugbetalen van een lening.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Onderpand</div><div class=\"sam-definitie-body\">bezit dat de bank mag verkopen als je niet terugbetaalt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Krediet</div><div class=\"sam-definitie-body\">de mogelijkheid om geld te lenen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Inflatie</div><div class=\"sam-definitie-body\">een algemene stijging van de prijzen.</div></div><div class=\"sam-onthoud\"><b>Let op de verschillen.</b> <b>«Rente»</b> is vergoeding voor geld, terwijl <b>«Aflossing»</b> lening terugbetalen is. <b>«Samengestelde interest»</b> is rente over rente, terwijl <b>«Enkelvoudige interest»</b> rente over startbedrag is. <b>«Sparen»</b> is geld opzijzetten, terwijl <b>«Lenen»</b> geld tijdelijk gebruiken is. <b>«Hypotheek»</b> is lening voor een huis, terwijl <b>«Krediet»</b> mogelijkheid om te lenen is.</div>"},"I":{"sv":[{"v":"Wat is een ondernemer?","o":["Iemand die een bedrijf start en risico neemt","Iemand in loondienst","Een klant","Een ambtenaar"],"c":0,"d":1,"u":"Iemand die een bedrijf start en risico neemt.","uo":["Klopt: iemand die een bedrijf start en risico neemt.","Dat is een werknemer.","Een klant koopt.","Iets anders."],"uh":"Iemand die een bedrijf start en risico neemt."},{"v":"Wat is een ondernemingsplan?","o":["Een belastingformulier","Een plan waarin je je bedrijf uitwerkt","Een verzekering","Een lening"],"c":1,"d":2,"u":"Een plan waarin je je bedrijf uitwerkt.","uo":["Nee, het juiste antwoord is «Een plan waarin je je bedrijf uitwerkt».","Klopt: een plan waarin je je bedrijf uitwerkt.","Nee, het juiste antwoord is «Een plan waarin je je bedrijf uitwerkt».","Nee, het juiste antwoord is «Een plan waarin je je bedrijf uitwerkt»."],"uh":"Een plan waarin je je bedrijf uitwerkt."},{"v":"Wat is startkapitaal?","o":["De belasting","De latere winst","Geld om te beginnen","Het loon"],"c":2,"d":1,"u":"Het geld dat je nodig hebt om te starten.","uo":["Belasting is iets anders.","Winst komt later.","Klopt: het geld dat je nodig hebt om te starten.","Loon is iets anders."],"uh":"Geld om te beginnen: Het geld dat je nodig hebt om te starten."},{"v":"Wat is marktonderzoek?","o":["Producten verkopen","Belasting berekenen","Loon uitbetalen","Onderzoek naar klanten en concurrenten"],"c":3,"d":2,"u":"Onderzoek naar je klanten en concurrenten.","uo":["Nee, het juiste antwoord is «Onderzoek naar klanten en concurrenten».","Nee, het juiste antwoord is «Onderzoek naar klanten en concurrenten».","Nee, het juiste antwoord is «Onderzoek naar klanten en concurrenten».","Klopt: onderzoek naar je klanten en concurrenten."],"uh":"Onderzoek naar je klanten en concurrenten."},{"v":"Wat is een doelgroep?","o":["De klanten die je wilt bereiken","Alle mensen","Je concurrenten","De overheid"],"c":0,"d":2,"u":"De groep klanten die je wilt bereiken.","uo":["Klopt: de groep klanten die je wilt bereiken.","Te breed, het juiste antwoord is «De klanten die je wilt bereiken».","Dat zijn juist rivalen.","Iets anders."],"uh":"De klanten die je wilt bereiken: De groep klanten die je wilt bereiken."},{"v":"Wat is een concurrent?","o":["Een klant","Een ander bedrijf dat hetzelfde aanbiedt","Een leverancier","De overheid"],"c":1,"d":2,"u":"Een rivaal die hetzelfde aanbiedt.","uo":["Een klant koopt.","Klopt: een rivaal die hetzelfde aanbiedt.","Een leverancier levert.","Iets anders."],"uh":"Een ander bedrijf dat hetzelfde aanbiedt: Een rivaal die hetzelfde aanbiedt."},{"v":"Wat is de kostprijs?","o":["De winst","De verkoopprijs","De kosten per product","De belasting"],"c":2,"d":2,"u":"De kosten per product.","uo":["Winst is iets anders.","De prijs bij verkoop is iets anders.","Klopt: de kosten per product.","Belasting is iets anders."],"uh":"De kosten per product."},{"v":"Wat is risico bij ondernemen?","o":["Zekere winst","Een verzekering","Een lening","De kans dat iets misgaat"],"c":3,"d":2,"u":"De kans dat iets misgaat en je geld verliest.","uo":["Winst is niet zeker.","Iets anders.","Iets anders.","Klopt: de kans dat iets misgaat en je geld verliest."],"uh":"De kans dat iets misgaat en je geld verliest."},{"v":"Wat is een investering?","o":["Geld uitgeven aan bedrijfsmiddelen","Geld weggooien","Belasting betalen","Sparen op de bank"],"c":0,"d":2,"u":"Geld uitgeven aan bedrijfsmiddelen.","uo":["Klopt: geld uitgeven aan bedrijfsmiddelen.","Nee, het juiste antwoord is «Geld uitgeven aan bedrijfsmiddelen».","Iets anders.","Iets anders."],"uh":"Geld uitgeven aan bedrijfsmiddelen."},{"v":"Wat is financiering?","o":["De winst","Hoe je aan geld voor je bedrijf komt","De belasting","De kostprijs"],"c":1,"d":2,"u":"De manier waarop je aan geld komt.","uo":["Winst is iets anders.","Klopt: de manier waarop je aan geld komt.","Belasting is iets anders.","Kostprijs is iets anders."],"uh":"Hoe je aan geld voor je bedrijf komt: De manier waarop je aan geld komt."},{"v":"Wat is de winstmarge?","o":["De belasting","De totale omzet","Verkoopprijs min kostprijs","Het startkapitaal"],"c":2,"d":2,"u":"Het verschil tussen verkoopprijs en kostprijs.","uo":["Belasting is iets anders.","Omzet is iets anders.","Klopt: het verschil tussen verkoopprijs en kostprijs.","Startkapitaal is iets anders."],"uh":"Verkoopprijs min kostprijs: Het verschil tussen verkoopprijs en kostprijs."},{"v":"Wat is een rechtsvorm?","o":["Een verzekering","Een marktonderzoek","Een lening","De juridische vorm van een bedrijf"],"c":3,"d":3,"u":"De juridische vorm, zoals een eenmanszaak.","uo":["Nee, het juiste antwoord is «De juridische vorm van een bedrijf».","Nee, het juiste antwoord is «De juridische vorm van een bedrijf».","Nee, het juiste antwoord is «De juridische vorm van een bedrijf».","Klopt: de juridische vorm, zoals een eenmanszaak."],"uh":"De juridische vorm, zoals een eenmanszaak."}],"begrippen":[{"t":"Ondernemer","d":"iemand die een bedrijf start en er risico mee neemt"},{"t":"Ondernemingsplan","d":"een plan waarin je je bedrijf uitwerkt"},{"t":"Startkapitaal","d":"het geld dat je nodig hebt om te beginnen"},{"t":"Investering","d":"geld dat je uitgeeft aan bedrijfsmiddelen"},{"t":"Marktonderzoek","d":"onderzoek naar klanten en concurrenten"},{"t":"Doelgroep","d":"de groep klanten die je wilt bereiken"},{"t":"Concurrent","d":"een ander bedrijf dat hetzelfde aanbiedt"},{"t":"Kostprijs","d":"de kosten per product"},{"t":"Winstmarge","d":"het verschil tussen verkoopprijs en kostprijs"},{"t":"Financiering","d":"de manier waarop je aan geld voor je bedrijf komt"},{"t":"Risico","d":"de kans dat iets misgaat en je geld verliest"},{"t":"Rechtsvorm","d":"de juridische vorm van een bedrijf, zoals een eenmanszaak"}],"sam":"<div class=\"sam-intro\">Een <strong>ondernemer</strong> start een bedrijf en neemt <strong>risico</strong>. In een <strong>ondernemingsplan</strong> werk je je idee uit: <strong>doelgroep</strong>, <strong>marktonderzoek</strong>, <strong>startkapitaal</strong> en de <strong>kostprijs</strong>.</div><div class=\"sam-head\">1. Een bedrijf starten</div><p>Een <strong>ondernemer</strong> begint een bedrijf en neemt daarbij <strong>risico</strong>: de kans dat het misgaat. In een <strong>ondernemingsplan</strong> werk je alles uit. Je hebt <strong>startkapitaal</strong> nodig en doet <strong>investeringen</strong> in bedrijfsmiddelen. Hoe je aan geld komt, heet de <strong>financiering</strong>; de <strong>rechtsvorm</strong> bepaalt onder meer wie aansprakelijk is.</p><div class=\"sam-head\">2. Klanten en prijs</div><p>Met <strong>marktonderzoek</strong> onderzoek je je klanten en <strong>concurrenten</strong>, zodat je je <strong>doelgroep</strong> kent. De <strong>kostprijs</strong> zijn de kosten per product; het verschil met de verkoopprijs is je <strong>winstmarge</strong>.</p><div class=\"sam-head\">Begrippen op een rij</div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Ondernemer</div><div class=\"sam-definitie-body\">iemand die een bedrijf start en er risico mee neemt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Ondernemingsplan</div><div class=\"sam-definitie-body\">een plan waarin je je bedrijf uitwerkt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Startkapitaal</div><div class=\"sam-definitie-body\">het geld dat je nodig hebt om te beginnen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Investering</div><div class=\"sam-definitie-body\">geld dat je uitgeeft aan bedrijfsmiddelen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Marktonderzoek</div><div class=\"sam-definitie-body\">onderzoek naar klanten en concurrenten.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Doelgroep</div><div class=\"sam-definitie-body\">de groep klanten die je wilt bereiken.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Concurrent</div><div class=\"sam-definitie-body\">een ander bedrijf dat hetzelfde aanbiedt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Kostprijs</div><div class=\"sam-definitie-body\">de kosten per product.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Winstmarge</div><div class=\"sam-definitie-body\">het verschil tussen verkoopprijs en kostprijs.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Financiering</div><div class=\"sam-definitie-body\">de manier waarop je aan geld voor je bedrijf komt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Risico</div><div class=\"sam-definitie-body\">de kans dat iets misgaat en je geld verliest.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Rechtsvorm</div><div class=\"sam-definitie-body\">de juridische vorm van een bedrijf, zoals een eenmanszaak.</div></div><div class=\"sam-onthoud\"><b>Let op de verschillen.</b> <b>«Ondernemingsplan»</b> is plan voor je bedrijf, terwijl <b>«Marktonderzoek»</b> onderzoek naar de markt is. <b>«Startkapitaal»</b> is geld om te starten, terwijl <b>«Investering»</b> geld in bedrijfsmiddelen is. <b>«Marktonderzoek»</b> is onderzoek naar de markt, terwijl <b>«Doelgroep»</b> jouw klanten is. <b>«Doelgroep»</b> is jouw klanten, terwijl <b>«Concurrent»</b> rivaal op de markt is.</div>"}});